options(stringsAsFactors=FALSE,warn=1,digits=16)
suppressPackageStartupMessages({library(jsonlite);library(GSVA);library(decoupleR);library(limma);library(fgsea)})
P<-'/mnt/BioDisk/wangmingyuan/tongbian_formal_20261012';A<-file.path(P,'07_animal_multiomics/GSE319612_DESeq2_v1');O<-file.path(P,'07_animal_multiomics/GSE319612_functional_integrative_v1');R<-file.path(P,'03_inputs/references')
