wr<-function(x,n)write.table(x,file.path(O,n),sep='\t',quote=FALSE,row.names=FALSE,na='NA');gmt<-function(p){x<-strsplit(readLines(p),'\t');setNames(lapply(x,function(z)unique(z[-c(1,2)])),sapply(x,'[',1))}
mapping<-read.delim(file.path(R,'Ensembl_human_mouse_one2one_20261013/human_mouse_all_homology.tsv'),check.names=FALSE)
names(mapping)<-c('human_id','human_symbol','mouse_id','mouse_symbol','type','confidence');m<-unique(mapping[mapping$type=='ortholog_one2one'&mapping$confidence==1&!is.na(mapping$confidence)&nzchar(mapping$human_id)&nzchar(mapping$mouse_id),]);stopifnot(!anyDuplicated(m$human_id),!anyDuplicated(m$mouse_id));wr(m,'references/Ensembl_high_confidence_one2one.tsv')
ms<-m[nzchar(m$human_symbol)&nzchar(m$mouse_symbol),];amb<-names(which(table(ms$human_symbol)>1));ms<-ms[!ms$human_symbol %in% amb,];wr(data.frame(ambiguous_human_symbol_excluded=amb),'audit/symbol_mapping_ambiguities.tsv')
convert<-function(gs)lapply(gs,function(g)unique(ms$mouse_symbol[ms$human_symbol %in% g]))
v<-read.delim(file.path(A,'tables/blind_VST_prefiltered.tsv'),check.names=FALSE);gene<-read.delim(file.path(A,'tables/MC_vs_NC_ALL_genes.tsv'),check.names=FALSE);symbol<-gene$gene_name[match(v$gene_id,gene$gene_id)];ok<-!is.na(symbol)&nzchar(symbol)&symbol!='-';M<-as.matrix(v[ok,-1]);sym<-symbol[ok];V<-rowsum(M,sym,reorder=TRUE)/as.numeric(table(sym)[sort(unique(sym))]);stopifnot(all(is.finite(V)));meta<-read.delim(file.path(A,'audit/metadata_verified.tsv'),check.names=FALSE);stopifnot(identical(colnames(V),meta$sample_id));meta$group<-factor(meta$group,levels=c('NC','MC','RG'))
wr(data.frame(symbol=rownames(V),V,check.names=FALSE),'tables/symbol_mean_VST.tsv');wr(data.frame(gene_id=v$gene_id,symbol=symbol,retained=ok),'audit/VST_symbol_mapping.tsv')
modules_h<-gmt(file.path(P,'03_inputs/GSE245885_pilot/genesets/host_modules_frozen.gmt'));modules<-convert(modules_h)
coverage<-data.frame(module=names(modules),human_genes=sapply(modules_h,length),mapped_mouse_genes=sapply(modules,length),detected=sapply(modules,function(g)sum(g %in% rownames(V))));stopifnot(nrow(coverage)==4,all(coverage$detected>=5));wr(coverage,'audit/ssGSEA_module_coverage.tsv')
for(n in names(modules))write(paste(c(n,'Ensembl high confidence one2one mapped from frozen human module',modules[[n]]),collapse='\t'),file=file.path(O,'references/mouse_modules_mapped.gmt'),append=TRUE)
cfg<-list(frozen_before_scoring_utc=format(Sys.time(),tz='UTC',usetz=TRUE),VST='same blind TRUE VST; duplicated symbols averaged',ssGSEA=list(minSize=5,alpha=.25,normalize=TRUE),VIPER='DoRothEA 1.22.0 mouse A-C; minsize5; pleiotropyTRUE; eset.filterFALSE; method scale; bootstraps0; cores1',contrasts=c('MC_vs_NC','RG_vs_MC'),BH='separate per score family and contrast; fgsea separately per collection and contrast; Fisher two directions is separate family',pathways='frozen MSigDB2026.1.Hs C2:CP and GO BP mapped to mouse using Ensembl high-confidence one-to-one; not native mouse MSigDB',fgsea=list(minSize=15,maxSize=500,eps=0,nPermSimple=10000,seed=20261012),Fisher='one-sided greater, humanSTC-control and mouseMC-NC; nominalP<.05 sets; common finite-test one-to-one gene background',crossomics_sample_pairing=FALSE)
write_json(cfg,file.path(O,'analysis_config_FROZEN.json'),auto_unbox=TRUE,pretty=TRUE)
ss<-GSVA::gsva(GSVA::ssgseaParam(exprData=V,geneSets=modules,minSize=5,maxSize=Inf,alpha=.25,normalize=TRUE,checkNA='yes',use='all.obs',verbose=FALSE),verbose=FALSE,BPPARAM=BiocParallel::SerialParam())
stopifnot(nrow(ss)==4,identical(colnames(ss),meta$sample_id),all(is.finite(ss)));wr(data.frame(feature=rownames(ss),ss,check.names=FALSE),'tables/ssGSEA_scores.tsv')
net<-read.delim(file.path(R,'dorothea_mm_ABC_v1.22.0.tsv'),check.names=FALSE);stopifnot(all(c('tf','target','mor') %in% names(net)));vp<-as.data.frame(decoupleR::run_viper(mat=V,network=net,.source='tf',.target='target',.mor='mor',minsize=5,verbose=FALSE,pleiotropy=TRUE,eset.filter=FALSE,method='scale',bootstraps=0,cores=1));wr(vp,'tables/VIPER_long.tsv');vm<-matrix(NA_real_,length(unique(vp$source)),nrow(meta),dimnames=list(sort(unique(vp$source)),meta$sample_id));for(i in seq_len(nrow(vp)))vm[vp$source[i],vp$condition[i]]<-vp$score[i];stopifnot(all(is.finite(vm)));wr(data.frame(feature=rownames(vm),vm,check.names=FALSE),'tables/VIPER_scores.tsv')
tf<-split(net$target,net$tf);wr(data.frame(TF=names(tf),network_targets=sapply(tf,function(g)length(unique(g))),detected_targets=sapply(tf,function(g)length(intersect(g,rownames(V)))),returned=names(tf) %in% rownames(vm)),'audit/VIPER_coverage.tsv')
des<-model.matrix(~0+group,meta);colnames(des)<-levels(meta$group);stopifnot(qr(des)$rank==3);contr<-makeContrasts(MC_vs_NC=MC-NC,RG_vs_MC=RG-MC,levels=des);summary<-list()
for(family in c('ssGSEA','VIPER')){
 mat<-if(family=='ssGSEA')ss else vm;fit<-eBayes(contrasts.fit(lmFit(mat,des),contr),trend=FALSE,robust=FALSE);saveRDS(fit,file.path(O,'models',paste0(family,'_limma.rds')));rr<-list()
 for(nm in colnames(contr)){
  se<-fit$stdev.unscaled[,nm]*sqrt(fit$s2.post);ci<-qt(.975,fit$df.total)*se;t<-data.frame(feature=rownames(mat),family=family,contrast=nm,delta_score=fit$coefficients[,nm],moderated_t=fit$t[,nm],P=fit$p.value[,nm],BH=p.adjust(fit$p.value[,nm],'BH'),CI95_low=fit$coefficients[,nm]-ci,CI95_high=fit$coefficients[,nm]+ci,n_NC=8,n_MC=8,n_RG=10)
  expected<-if(nm=='MC_vs_NC')rowMeans(mat[,meta$group=='MC'])-rowMeans(mat[,meta$group=='NC']) else rowMeans(mat[,meta$group=='RG'])-rowMeans(mat[,meta$group=='MC']);stopifnot(max(abs(t$delta_score-expected))<1e-8)
  wr(t,paste0('tables/',family,'_',nm,'_ALL.tsv'));rr[[nm]]<-t;summary[[paste(family,nm)]]<-data.frame(family=family,contrast=nm,tested=nrow(t),nominal=sum(t$P<.05),BH=sum(t$BH<.05))
 }
 a<-rr[[1]];b<-rr[[2]];r<-data.frame(feature=a$feature,disease_delta=a$delta_score,disease_P=a$P,disease_BH=a$BH,intervention_delta=b$delta_score,intervention_P=b$P,intervention_BH=b$BH);r$reverse_nominal<-with(r,disease_P<.05&intervention_P<.05&disease_delta*intervention_delta<0);wr(r,paste0('tables/',family,'_opposite_direction_ALL.tsv'))
}
cat('SSGSEA_VIPER_COMPLETE\n');flush.console()
for(coll in c('C2_CP','GO_BP')){
 human<-gmt(file.path(R,'msigdbr_26.1.0_20261012',paste0(coll,'.human.symbols.gmt')));pathways<-convert(human);saveRDS(pathways,file.path(O,'references',paste0(coll,'_mapped_mouse.rds')))
 for(nm in c('MC_vs_NC','RG_vs_MC')){
  a<-read.delim(file.path(A,'tables',paste0(nm,'_ALL_genes.tsv')),check.names=FALSE);a<-a[is.finite(a$pvalue)&is.finite(a$stat)&!is.na(a$gene_name)&nzchar(a$gene_name)&a$gene_name!='-',];a<-a[order(-a$baseMean,a$gene_id),];a<-a[!duplicated(a$gene_name),];a<-a[order(-a$stat,a$gene_name),];stats<-setNames(a$stat,a$gene_name);wr(a,paste0('audit/',nm,'_symbol_Wald_ranking.tsv'))
  cv<-data.frame(pathway=names(pathways),human_size=sapply(human,length),mapped_mouse_size=sapply(pathways,length),detected_size=sapply(pathways,function(g)sum(g %in% names(stats))));cv$eligible<-cv$detected_size>=15&cv$detected_size<=500;wr(cv,paste0('audit/',coll,'_',nm,'_coverage_ALL.tsv'))
  set.seed(20261012);warn<-character();res<-withCallingHandlers(as.data.frame(fgsea::fgseaMultilevel(pathways=pathways,stats=stats,minSize=15,maxSize=500,eps=0,nPermSimple=10000,nproc=1)),warning=function(w){warn<<-c(warn,conditionMessage(w));invokeRestart('muffleWarning')});saveRDS(res,file.path(O,'models',paste0(coll,'_',nm,'_fgsea.rds')));writeLines(warn,file.path(O,'audit',paste0(coll,'_',nm,'_warnings.txt')))
  res$leadingEdge<-sapply(res$leadingEdge,paste,collapse=';');res$BH<-p.adjust(res$pval,'BH');res$contrast<-nm;res$collection<-coll;wr(res,paste0('tables/',coll,'_',nm,'_fgsea_ALL.tsv'));summary[[paste(coll,nm)]]<-data.frame(family=paste0('fgsea_',coll),contrast=nm,tested=sum(is.finite(res$pval)),nominal=sum(res$pval<.05,na.rm=TRUE),BH=sum(res$BH<.05,na.rm=TRUE));cat('FGSEA_COMPLETE',coll,nm,'\n');flush.console()
 }
}
h<-read.delim(file.path(P,'05_human_RNA/R_DESeq2_bridge_v1/R_DESeq2_all_genes.tsv'),check.names=FALSE);stopifnot('ensembl_id' %in% names(h));h$human_id<-sub('\\.[0-9]+$','',h$ensembl_id);a<-read.delim(file.path(A,'tables/MC_vs_NC_ALL_genes.tsv'),check.names=FALSE);a$mouse_id<-sub('\\.[0-9]+$','',a$gene_id);stopifnot(!anyDuplicated(h$human_id),!anyDuplicated(a$mouse_id));bg<-merge(m,h[,c('human_id','log2FoldChange','pvalue','padj')],by='human_id');names(bg)[names(bg) %in% c('log2FoldChange','pvalue','padj')]<-c('human_log2FC','human_P','human_BH');bg<-merge(bg,a[,c('mouse_id','log2FoldChange','pvalue','BH')],by='mouse_id');names(bg)[names(bg) %in% c('log2FoldChange','pvalue','BH')]<-c('mouse_log2FC','mouse_P','mouse_BH');bg<-bg[is.finite(bg$human_P)&is.finite(bg$mouse_P),];stopifnot(!anyDuplicated(bg$human_id),!anyDuplicated(bg$mouse_id));wr(bg,'tables/human_mouse_common_testable_background.tsv');ff<-list()
for(direction in c('up','down')){
 sign<-if(direction=='up')1 else -1;hu<-bg$human_P<.05&bg$human_log2FC*sign>0;mo<-bg$mouse_P<.05&bg$mouse_log2FC*sign>0;tt<-matrix(c(sum(hu&mo),sum(hu&!mo),sum(!hu&mo),sum(!hu&!mo)),nrow=2,byrow=TRUE);f<-fisher.test(tt,alternative='greater');ff[[direction]]<-data.frame(direction=direction,background_n=nrow(bg),human_set_n=sum(hu),mouse_set_n=sum(mo),overlap_n=sum(hu&mo),both=tt[1,1],human_only=tt[1,2],mouse_only=tt[2,1],neither=tt[2,2],OR=unname(f$estimate),P=f$p.value,CI95_one_sided_lower=f$conf.int[1],CI95_one_sided_upper=f$conf.int[2]);wr(bg[hu&mo,],paste0('tables/human_mouse_',direction,'_overlap_genes.tsv'))
}
f<-do.call(rbind,ff);f$BH<-p.adjust(f$P,'BH');wr(f,'tables/human_mouse_directional_Fisher.tsv');wr(do.call(rbind,summary),'tables/analysis_summary.tsv');capture.output(sessionInfo(),file=file.path(O,'audit/sessionInfo.txt'));write_json(list(status='COMPUTE_COMPLETE',summary=summary,Fisher=f,mapping_pairs=nrow(m),gene_set_mapping='frozen human MSigDB via Ensembl high-confidence one-to-one; no new MSigDB downloaded',crossomics_pairing=FALSE,completed_utc=format(Sys.time(),tz='UTC',usetz=TRUE)),file.path(O,'COMPUTE_COMPLETE.json'),pretty=TRUE,auto_unbox=TRUE);print(as.data.frame(do.call(rbind,summary)));print(as.data.frame(f))
